Q: Postgres function: return multiple tables A: <p><strong>this works</strong></p>
<pre><code>CREATE OR REPLACE FUNCTION public.func_test(id integer ,ref1 refcursor,ref2 refcursor)
 RETURNS SETOF refcursor
 LANGUAGE plpgsql
AS $function$
BEGIN
    OPEN ref1 FOR SELECT * FROM table1;
    RETURN NEXT ref1;
    OPEN ref2 FOR SELECT * FROM table2;
    RETURN NEXT ref2;
END;
$function$
;
</code></pre>
<p><strong>execute in sql</strong></p>
<pre><code>BEGIN;
    SELECT func_test(69, 'Ref1', 'Ref2');
    FETCH ALL IN &quot;Ref1&quot;;
    FETCH ALL IN &quot;Ref2&quot;;
COMMIT;
</code></pre>
<p><strong>execute in python</strong></p>
<pre><code>import psycopg2

conn = psycopg2.connect(database = &quot;name&quot;, user = &quot;user&quot;, password = &quot;pass&quot;, host = &quot;127.0.0.1&quot;, port = &quot;5432&quot;)
cur = conn.cursor()
cur.execute(&quot;SELECT * FROM func_test(69, 'Ref1', 'Ref2');&quot;)
cur.execute('FETCH ALL IN &quot;Ref1&quot;;')
tbl1 = cur.fetchall()
print(tbl1)
cur.execute('FETCH ALL IN &quot;Ref1&quot;;')
tbl2 = cur.fetchall()
print(tbl2)
</code></pre>
